function addExp(amount){const beforeLevel=state.level,beforeStats=stats(beforeLevel);let levels=0;state.exp+=amount;while(state.level<MAX_LEVEL){const need=expForNext(state.level);if(state.exp<need)break;state.exp-=need;state.level++;levels++}if(state.level>=MAX_LEVEL)state.exp=0;if(levels){pendingLevelDetails={beforeLevel,afterLevel:state.level,before:beforeStats,after:stats(state.level)};setTimeout(showLevelStatus,120)}return levels}
