const rouletteMaps=[
  {name:'まゆへの草原ロード',chapter:'MAP 1・MAYU ROUTE',boss:'mayu',stage:0,squares:['start','battle','heal','damage','xp','battle','mini','battle','damage','heal','xp','battle','mini','battle','boss']},
  {name:'こうきの最終試験ロード',chapter:'MAP 2・KOUKI ROUTE',boss:'kouki',stage:5,squares:['start','battle','xp','damage','mini','heal','battle','xp','battle','damage','mini','xp','heal','battle','damage','xp','mini','battle','heal','boss']}
];
const squareInfo={start:['🏠','スタート'],battle:['⚔','敵マス'],mini:['🐾','小ボスマス'],damage:['💥','ダメージマス'],heal:['💚','回復マス'],xp:['⭐','経験値マス'],boss:['👑','ボスマス']};
