showMap=showBoardMap;
function xpForBoardLevels(){return state.level>=MAX_LEVEL?0:Math.max(1,Math.round(expForNext(state.level)*.5))}
async function rollRoulette(){if(rouletteBusy)return;normalizeBoardState();const map=rouletteMaps[state.board],goal=map.squares.length-1;if(state.boardPos===goal){startBoardBoss();return}rouletteBusy=true;$('#advanceBtn').disabled=true;const display=$('#rouletteNumber');display.classList.add('spinning');let result=1;for(let i=0;i<13;i++){result=1+Math.floor(Math.random()*6);display.textContent=result;beep(300+i*24,.035);await wait(65+i*5)}display.classList.remove('spinning');const remaining=goal-state.boardPos;if(result>remaining){rouletteBusy=false;$('#advanceBtn').disabled=false;$('#mapMessage').textContent=`${result}！ ゴールまであと${remaining}マス。ぴったりではないので、その場にとどまった！`;beep(145,.18);save();return}state.boardPos+=result;renderBoardNodes();$('#goalDistance').textContent=state.boardPos===goal?'ボスマスに到着！':`ボスまで あと${goal-state.boardPos}マス`;save();await wait(650);await resolveBoardSquare(map.squares[state.boardPos])}
async function resolveBoardSquare(type){if(type==='battle'){beginMobBattle();battle.boardBattle=true;battle.boardKind='battle';return}if(type==='mini'){beginBoardMini();return}if(type==='boss'){startBoardBoss();return}const s=stats();if(type==='damage'){const damage=Math.max(3,Math.round(s.maxHp*(state.board?0.24:0.16)));state.hp=Math.max(1,state.hp-damage);showBoardMap(`💥 落とし穴！ HPが ${damage}減った！`);beep(110,.18);return}if(type==='heal'){const hpBefore=state.hp,mpBefore=state.mp;state.hp=Math.min(s.maxHp,state.hp+Math.round(s.maxHp*.45));state.mp=Math.min(s.maxMp,state.mp+Math.round(s.maxMp*.35));showBoardMap(`💚 いやしの泉！ HP＋${state.hp-hpBefore}、MP＋${state.mp-mpBefore}！`);beep(720,.18);return}if(type==='xp'){const amount=xpForBoardLevels(state.board?9:2),levels=addExp(amount),newStats=stats();if(levels){state.hp=newStats.maxHp;state.mp=newStats.maxMp;state.waters=3}showBoardMap(`⭐ 経験値 ${amount}！ レベルが ${levels}上がった！`);beep(900,.2);return}showBoardMap()}
