let rouletteCycleTimer=null,rouletteCycleValue=1;
function stopRouletteCycle(){if(rouletteCycleTimer){clearInterval(rouletteCycleTimer);rouletteCycleTimer=null}const trigger=$('#rouletteTrigger');if(trigger)trigger.classList.remove('cycling')}
function startRouletteCycle(){stopRouletteCycle();const trigger=$('#rouletteTrigger'),display=$('#rouletteNumber');if(!trigger||!display||$('#mapScreen').classList.contains('hidden'))return;trigger.disabled=false;trigger.classList.remove('confirmed');trigger.classList.add('cycling');display.textContent=rouletteCycleValue;rouletteCycleTimer=setInterval(()=>{rouletteCycleValue=rouletteCycleValue%3+1;display.textContent=rouletteCycleValue},95)}
