async function advanceFixedRoulette(result){normalizeRouteV2();const map=routeMapsV2[state.board],current=map.nodes[state.routeNode],remaining=map.total-current.d;if(!remaining){askBossV2();return}if(result>remaining){rouletteBusy=false;$('#mapMessage').textContent=`${result}！ ボスまであと${remaining}マス。ぴったりではないので進まない！`;beep(145,.18);setTimeout(startRouletteCycle,650);return}for(let step=0;step<result;step++){const node=map.nodes[state.routeNode];let next;if(node.next.length>1){next=state.routeNext||await askRouteV2(node);delete state.routeNext}else next=node.next[0];await moveSugorokuV4(next);beep(440+step*35,.06)}save();const landed=map.nodes[state.routeNode];if(landed.type==='branch'){state.routeNext=await askRouteV2(landed);showSugorokuV4('進むルートを決めた！ 次のルーレットで出発！');return}await resolveRouteV2Square(landed.type)}
async function stopAndAdvanceRoulette(){if(rouletteBusy||!rouletteCycleTimer)return;rouletteBusy=true;const trigger=$('#rouletteTrigger'),display=$('#rouletteNumber'),result=rouletteCycleValue;stopRouletteCycle();trigger.disabled=true;trigger.classList.add('confirmed');display.textContent=result;beep(920,.18);$('#mapMessage').textContent=`${result}で確定！ たるとが進むよ！`;await wait(850);trigger.classList.remove('confirmed');await advanceFixedRoulette(result);if(!$('#mapScreen').classList.contains('hidden')&&!rouletteCycleTimer&&!rouletteBusy)startRouletteCycle()}
$('#rouletteTrigger').onclick=stopAndAdvanceRoulette;
const enemyActionBeforeStun=enemyAction;
enemyAction=async function(enemy,s){if(enemy.stunTurns>0){enemy.stunTurns--;renderEnemies();updateBattle();log(`${enemy.name}は 目を回して動けない！\n残り ${enemy.stunTurns}回`);beep(210,.12);await wait(560);return}return enemyActionBeforeStun(enemy,s)};
const heroActionBeforeAdvanced=heroAction;
heroAction=async function(type,s){const buffWasActive=battle.heroAtkBuffTurns>0,buffMultiplier=battle.heroAtkBuffMultiplier||1.5,boosted={...s,atk:s.atk*(buffWasActive?buffMultiplier:1)},target=activeEnemy(),advanced=['dig','snack','tackle','father','motherSupport','rampage','supreme'].includes(type);if(!advanced){await heroActionBeforeAdvanced(type,boosted);if(buffWasActive){battle.heroAtkBuffTurns--;if(!battle.heroAtkBuffTurns)battle.heroAtkBuffMultiplier=1}return}let text='';state.mp-=skills[type].mp;if(type==='dig'){battle.evadeNext=true;text='たるとは 穴を掘ってかくれた！\n次の攻撃を1回だけ完全回避！';beep(280,.14)}if(type==='snack'){battle.heroAtkBuffTurns=3;battle.heroAtkBuffMultiplier=1.5;text='たるとは おやつを食べた！\n攻撃力が1.5倍！ 3回継続！';beep(780,.16)}if(type==='tackle'){const dmg=Math.max(1,Math.round(boosted.atk*.5));target.currentHp-=dmg;showNumber(dmg,'damage',target);hitEnemies(false);text=`先制！ たるとタックル！\n${target.name}に ${dmg}ダメージ！`;beep(670,.13)}if(type==='father'){const hpBefore=state.hp,mpBefore=state.mp;state.hp=Math.min(s.maxHp,state.hp+Math.round(s.maxHp*.25));state.mp=Math.min(s.maxMp,state.mp+Math.round(s.maxMp*.2));showNumber(state.hp-hpBefore,'heal');text=`とーちゃんの応援！\nHP＋${state.hp-hpBefore}、MP＋${state.mp-mpBefore}！`;beep(820,.18)}if(type==='motherSupport'){battle.heroAtkBuffTurns=2;battle.heroAtkBuffMultiplier=2;text='かーちゃんの応援！\n攻撃力が2倍！ 2回継続！';beep(940,.2)}if(type==='rampage'){let total=0;aliveEnemies().forEach(e=>{const dmg=Math.max(5,Math.round(boosted.atk*3*(.9+Math.random()*.2)));e.currentHp-=dmg;total+=dmg;showNumber(dmg,'critical',e)});hitEnemies(true);text=`たると大暴走！！\n敵全体に合計 ${total}ダメージ！`;beep(105,.24)}if(type==='supreme'){const dmg=100+Math.floor(Math.random()*201);target.currentHp-=dmg;battle.damageHalfTurns=3;showNumber(dmg,'critical',target);hitEnemies(false);text=`天上天下唯我独尊！！\n${target.name}に ${dmg}ダメージ！ 受けるダメージ半減が3回！`;beep(1020,.25)}if(buffWasActive&&!['snack','motherSupport'].includes(type)){battle.heroAtkBuffTurns--;if(!battle.heroAtkBuffTurns)battle.heroAtkBuffMultiplier=1}log(text);updateBattle();await wait(720)};
const enemyActionBeforeAdvanced=enemyAction;
enemyAction=async function(enemy,s){if(enemy.stunTurns>0)return enemyActionBeforeAdvanced(enemy,s);if(battle.evadeNext){battle.evadeNext=false;log(` ${enemy.name}の攻撃！\nたるとは穴にかくれて完全回避！`);beep(360,.14);await wait(560);return}const hpBefore=state.hp;await enemyActionBeforeAdvanced(enemy,s);if(battle.damageHalfTurns>0&&state.hp<hpBefore){const raw=hpBefore-state.hp,restored=Math.floor(raw/2);state.hp+=restored;battle.damageHalfTurns--;showNumber(restored,'heal');log(`天上天下唯我独尊の守り！\n受けたダメージを ${raw-restored} に半減！ 残り${battle.damageHalfTurns}回`);updateBattle();await wait(380)}};
