function centerHex(smooth=true){const cell=hexCell(state.hex.player),view=$('#mapBackdrop');view.scrollTo({left:Math.max(0,cell.x-view.clientWidth*.38),behavior:smooth?'smooth':'auto'})}
function showHexMap(custom){stopRouletteCycle();normalizeHexState();playMusic('map');show('#mapScreen');const screen=$('#mapScreen'),mustRoll=state.hex.movesLeft<=0;screen.classList.add('hex-mode');screen.classList.toggle('await-roll',mustRoll);renderHexMap();const map=hexMaps[state.board],s=stats(),boss=hexCell(state.hex.player).type==='boss';$('#mapBackdrop').classList.toggle('final-map',state.board===1);$('#mapLevel').textContent=`${state.level}/${MAX_LEVEL}`;$('#mapHp').textContent=`${state.hp}/${s.maxHp}`;$('#mapMp').textContent=`${state.mp}/${s.maxMp}`;$('#mapCarrots').textContent=state.carrots;$('#questHeaderTitle').textContent=map.name;$('#chapterLabel').textContent=map.chapter;$('#locationName').textContent=map.name;$('#mapMessage').textContent=custom||(mustRoll?'ルーレットをタップして、このターンの移動数を決めよう！':`あと${state.hex.movesLeft}マス。光る六角形をタッチ！`);$('#goalDistance').textContent=boss?'ボスマスに到着！':mustRoll?`ターン ${state.hex.turn+1}・敵 ${state.hex.enemies.length}体`:`残り ${state.hex.movesLeft}マス`;$('#rouletteNumber').textContent=mustRoll?'?':state.hex.movesLeft;$('#mapHealBtn').disabled=false;rouletteBusy=false;hexMoveBusy=false;save();if(boss&&state.hex.movesLeft<=0&&!state.hex.bossReroll)setTimeout(askBossV2,250)}
showMap=showHexMap;
function hexNextOnRoute(){const index=HEX_ROUTE.indexOf(state.hex.player);return HEX_ROUTE[Math.min(HEX_ROUTE.length-1,index+1)]}
