const skillUnlockTable=[['しっぽを振り回す',3],['穴を掘る',7],['おやつパワー',8],['たるとタックル',12],['とーちゃん応援',18],['友情の呼び声',20],['かーちゃん応援',25],['たると大暴走',35],['天上天下唯我独尊',40]];
