function spawnDefeatBonusEnemies(count=3){normalizeHexState();const occupied=new Set(state.hex.enemies.map(enemy=>enemy.cell)),map=hexMaps[state.board],nests=map.cells.filter(cell=>cell.type==='spawn'),nearNests=[...new Set(nests.flatMap(cell=>[cell.id,...hexNeighbors(cell.id)]))],valid=id=>{const cell=map.cells[id];return cell&&cell.type!=='mountain'&&cell.type!=='start'&&cell.type!=='boss'&&id!==state.hex.player&&!occupied.has(id)},preferred=seededShuffle(nearNests.filter(valid),Date.now()),fallback=seededShuffle(map.cells.map(cell=>cell.id).filter(valid),Date.now()+71),cells=[...preferred,...fallback.filter(id=>!preferred.includes(id))].slice(0,count);cells.forEach((cell,index)=>{occupied.add(cell);state.hex.enemies.push({id:`defeat-bonus-${Date.now()}-${index}`,cell,icon:['👾','🐺','🐍'][index%3],initial:false})});return cells.length}
