const finishAtbBeforeAutoReviveV54=finishAtbBattle;
finishAtbBattle=async function(){battle.autoRevive=battle.autoRevive||{};if(state.hp<=0&&battle.autoRevive.hero){battle.autoRevive.hero=false;state.hp=Math.round(stats().maxHp*.5);battle.heroDownNotified=false;await heroRevivalBanner('天使のペロペロ！','たるとがHP50％で復活！');updateBattle()}if(battle.mayu&&battle.mayu.hp<=0&&battle.autoRevive.mayu){battle.autoRevive.mayu=false;battle.mayu.hp=Math.round(battle.mayu.maxHp*.5);await heroRevivalBanner('青春リスタート！','まゆがHP50％で復活！');updateBattle()}return finishAtbBeforeAutoReviveV54()};
function openEffectsV54(){const was=battle&&battle.awaitingAtb;if(battle)battle.awaitingAtb='guide';const sections=[['たるとの必殺技',tarutoSpecialsV54.filter(def=>state.level>=def.lv)],['たるとの回復技',tarutoHealsV54.filter(def=>state.level>=def.lv)]];if(battle&&battle.mayu){sections.push(['まゆの必殺技',mayuSpecialsV54.filter(def=>battle.mayu.level>=def.lv)],['まゆの回復技',mayuHealsV54.filter(def=>battle.mayu.level>=def.lv)])}$('#effectsList').innerHTML=sections.map(([title,list])=>`<section><h3>${title}</h3>${list.map(def=>`<div><b>${def.name}</b><em>LV${def.lv}・MP ${def.mp}</em><small>${def.effect}</small></div>`).join('')}</section>`).join('');$('#effectsModal').classList.remove('hidden');$('#effectsClose').onclick=()=>{$('#effectsModal').classList.add('hidden');if(battle)battle.awaitingAtb=was}}
