const enemyActionBeforeLungeV521=enemyAction;
enemyAction=async function(enemy,s){const unit=document.querySelector(`.enemy-unit[data-id="${enemy.id}"]`);if(unit){unit.classList.remove('enemy-attacking');void unit.offsetWidth;unit.classList.add('enemy-attacking');await wait(180)}try{return await enemyActionBeforeLungeV521(enemy,s)}finally{if(unit){unit.classList.add('enemy-returning');setTimeout(()=>unit.classList.remove('enemy-attacking','enemy-returning'),260)}}};
// Version 5.2: speed-based active time battle
let atbTimer=null,atbTickBusy=false;
function stopAtb(){if(atbTimer){clearInterval(atbTimer);atbTimer=null}atbTickBusy=false}
function atbActors(){if(!battle)return[];const ailments=ensureHeroAilments(),actors=[];if(state.hp>0)actors.push({key:'hero',kind:'hero',name:'たると',icon:'🐶',spd:stats().spd*(ailments.speedDown>0?.5:1)});if(battle.mayu&&battle.mayu.hp>0)actors.push({key:'mayu',kind:'mayu',name:'まゆ',icon:'👩🏻‍🎓',spd:battle.mayu.spd});aliveEnemies().forEach(enemy=>actors.push({key:`enemy-${enemy.id}`,kind:'enemy',name:enemy.name,icon:enemy.icon||'👤',spd:enemy.spd,enemy}));return actors}
function syncAtbGauges(){battle.atb=battle.atb||{};const actors=atbActors(),keys=new Set(actors.map(actor=>actor.key));actors.forEach(actor=>{if(!Number.isFinite(battle.atb[actor.key]))battle.atb[actor.key]=0});Object.keys(battle.atb).forEach(key=>{if(!keys.has(key))delete battle.atb[key]})}
function renderAtbMeters(activeKey=''){if(!battle||!battle.atbMode)return;syncAtbGauges();const selectedKey=activeKey||(battle.awaitingAtb==='hero'?'hero':battle.awaitingAtb==='mayu'?'mayu':'');[['hero',state.hp>0],['mayu',Boolean(battle.mayu&&battle.mayu.hp>0)]].forEach(([key,alive])=>{const gauge=document.querySelector(`[data-atb-key="${key}"]`);if(!gauge)return;gauge.classList.toggle('defeated',!alive);const status=gauge.closest('.hero-status');if(status)status.classList.remove('current-atb-turn');if(!alive){const fill=gauge.querySelector('div i'),text=gauge.querySelector('b');if(fill)fill.style.width='0%';if(text)text.textContent='戦闘不能'}});atbActors().forEach(actor=>{const value=Math.min(100,battle.atb[actor.key]||0),gauge=document.querySelector(`[data-atb-key="${actor.key}"]`);if(!gauge)return;const isActive=selectedKey===actor.key&&value>=100;gauge.classList.toggle('ready',value>=100);gauge.classList.toggle('active',selectedKey===actor.key);const status=gauge.closest('.hero-status');if(status)status.classList.toggle('current-atb-turn',isActive);const fill=gauge.querySelector('div i'),text=gauge.querySelector('b');if(fill)fill.style.width=`${value}%`;if(text)text.textContent=value>=100?'行動！':`${Math.floor(value)}%`})}
async function finishAtbBattle(){const mayuAlive=Boolean(battle.mayu&&battle.mayu.hp>0);if(state.hp<=0&&mayuAlive&&!battle.heroDownNotified){battle.heroDownNotified=true;closeMenus();$('#commands').classList.add('hidden');log('たるとは力尽きた！\nでも、まゆが戦いを続ける！');renderAtbMeters();await wait(500)}if(state.hp<=0&&!mayuAlive){stopAtb();lose();return true}if(!aliveEnemies().length){if(await tryKoukiRevival()){syncAtbGauges();renderAtbMeters();return false}stopAtb();win();return true}return false}
function startAtbClock(){stopAtb();atbTimer=setInterval(runAtbTick,80)}
async function runAtbTick(){if(atbTickBusy||!battle||!battle.atbMode||battle.awaitingAtb||$('#battleScreen').classList.contains('hidden'))return;atbTickBusy=true;try{if(await finishAtbBattle())return;syncAtbGauges();const actors=atbActors();actors.forEach(actor=>battle.atb[actor.key]=Math.min(100,(battle.atb[actor.key]||0)+1.2+actor.spd/25));renderAtbMeters();const ready=actors.filter(actor=>battle.atb[actor.key]>=100).sort((a,b)=>b.spd-a.spd)[0];if(!ready)return;if(ready.kind==='hero'){const ailments=ensureHeroAilments();if(ailments.stun>0||ailments.burn>0){battle.atb.hero=0;if(ailments.stun>0)ailments.stun--;log('たるとは行動できない！ ATBゲージがリセットされた！');await applyHeroAilmentTick(stats());renderAtbMeters('hero');await wait(420);return}battle.awaitingAtb='hero';busy=false;$('#commands').classList.remove('hidden');$$('#commands button,#skillMenu button,#healMenu button').forEach(button=>button.disabled=false);log('たるとのATBゲージが満タン！ 行動を選んでください');renderAtbMeters('hero');return}if(ready.kind==='mayu'){battle.awaitingAtb='mayu';busy=false;$('#commands').classList.add('hidden');$('#mayuCommandMenu').classList.remove('hidden');$('#mayuCommandMp').textContent=`MP ${battle.mayu.mp}/${battle.mayu.maxMp}`;log('まゆのATBゲージが満タン！ 行動を選んでください');renderAtbMeters('mayu');return}battle.atb[ready.key]=0;renderAtbMeters(ready.key);await enemyAction(ready.enemy,stats());if(battle.fled||$('#battleScreen').classList.contains('hidden')){stopAtb();return}battle.guard=false;await finishAtbBattle()}finally{atbTickBusy=false}}
const startBattleBeforeAtbV52=startBattle;
startBattle=function(text){startBattleBeforeAtbV52(text);battle.partyTurnMode=false;battle.atbMode=true;battle.awaitingAtb=null;battle.atb={};$('#commands').classList.add('hidden');$('#mayuCommandMenu').classList.add('hidden');toggleCommands(false);syncAtbGauges();renderAtbMeters();log(`${text}\n素早さに応じてATBゲージがたまる！`);setTimeout(startAtbClock,350)};
const actBeforeAtbV52=act;
act=async function(type){if(!battle||!battle.atbMode)return actBeforeAtbV52(type);if(busy||battle.awaitingAtb!=='hero')return;if(type==='supreme'&&state.mp<=0){log('天上天下唯我独尊を使うMPがたりない！');return}if(!canQueueHeroAction(type))return;busy=true;battle.awaitingAtb=null;battle.atb.hero=0;closeMenus();toggleCommands(false);renderAtbMeters('hero');await heroAction(type,stats());if(state.hp>0&&aliveEnemies().length)await applyBleeding(stats());updateBattle();if(await finishAtbBattle())return;renderEnemies();renderAtbMeters()};
async function submitAtbMayuAction(action){if(!battle||!battle.atbMode||busy||battle.awaitingAtb!=='mayu')return;const costs={attack:0,report:6,talk:7,latte:8},cost=costs[action]||0;if(battle.mayu.mp<cost){log(`まゆのMPが足りない！ MP${cost}必要。`);beep(160,.12);return}busy=true;battle.awaitingAtb=null;battle.atb.mayu=0;$('#mayuCommandMenu').classList.add('hidden');battle.mayuChosenAction=action;battle.mayuActedThisRound=false;renderAtbMeters('mayu');await executeMayuCommand();updateBattle();if(await finishAtbBattle())return;renderEnemies();renderAtbMeters()}
$$('[data-mayu-action]').forEach(button=>button.onclick=()=>submitAtbMayuAction(button.dataset.mayuAction));
const actBeforeFinalSkillsV54=act;
act=async function(type){const def=allTarutoActionsV54.find(item=>item.type===type);if(!def){const result=await actBeforeFinalSkillsV54(type);if(battle&&battle.atbMode&&!$('#battleScreen').classList.contains('hidden'))await tickRegenV54('hero');return result}if(!battle||!battle.atbMode||busy||battle.awaitingAtb!=='hero')return;if(state.level<def.lv||state.mp<def.mp){log(`「${def.name}」を使うMPが足りない！`);return}busy=true;let target=null;if(actionNeedsTargetV54(def)){battle.awaitingAtb='target';target=await choosePartyTargetV54(def.target==='deadOne');if(!target){battle.awaitingAtb='hero';busy=false;$('#commands').classList.remove('hidden');return}}battle.awaitingAtb='resolving';battle.atb.hero=0;closeMenus();toggleCommands(false);renderAtbMeters('hero');await executeTarutoActionV54(def,target);await tickRegenV54('hero');battle.awaitingAtb=null;if(await finishAtbBattle())return;renderEnemies();renderAtbMeters()};

// Version 5.4: field recovery and status also use techniques instead of items.
const fieldHealsV54=new Set(['h_cabbage','h_carrot','h_lick','h_father','h_infinite']);
openMapHealMenu=function(){if(!state||!state.hex)return;const learned=tarutoHealsV54.filter(def=>state.level>=def.lv&&fieldHealsV54.has(def.type));$('#mapHealActions').innerHTML=learned.map(def=>`<button type="button" data-field-heal="${def.type}"><span>💚</span><b>${def.name}</b><small>MP ${def.mp}・${def.effect}</small></button>`).join('')||'<p>マップで使える回復技はまだありません。</p>';$('#mapHealMenu').classList.remove('hidden');$('#mapHealActions').querySelectorAll('[data-field-heal]').forEach(button=>button.onclick=()=>useFieldHealV54(button.dataset.fieldHeal));beep(520,.08)};
function useFieldHealV54(type){const def=tarutoHealsV54.find(item=>item.type===type),s=stats();if(!def)return;if(state.mp<def.mp){beep(180,.12);showHexMap(`「${def.name}」を使うMPが足りない！`);closeMapHealMenu();return}if(state.hp>=s.maxHp&&type!=='h_father'){beep(180,.12);showHexMap('HPはすでに満タン！');closeMapHealMenu();return}state.mp-=def.mp;const ratio=type==='h_cabbage'||type==='h_lick'?.5:type==='h_father'?.8:1,before=state.hp;state.hp=Math.min(s.maxHp,state.hp+Math.round(s.maxHp*ratio));if(type==='h_father')state.mp=Math.min(s.maxMp,state.mp+Math.round(s.maxMp*.2));closeMapHealMenu();save();showHexMap(`${def.name}！ HPが${state.hp-before}回復した！`);playSfx('heal')}
$('#mapHealBtn').onclick=openMapHealMenu;

openMapStatus=function(){const s=stats(),next=state.level>=MAX_LEVEL?'MAX':Math.max(0,expForNext(state.level)-state.exp),parameters=[['レベル',`${state.level}/${MAX_LEVEL}`],['HP',`${state.hp}/${s.maxHp}`],['MP',`${state.mp}/${s.maxMp}`],['こうげき',Math.round(s.atk)],['ぼうぎょ',Math.round(s.def)],['すばやさ',Math.round(s.spd)],['経験値',state.exp],['次のレベルまで',next]];$('#mapStatusTitle').textContent='たるとのステータス';$('#mapStatusParameters').innerHTML=parameters.map(([label,value])=>`<span><small>${label}</small><b>${value}</b></span>`).join('');$('#mapStatusSkills').innerHTML=[...tarutoSpecialsV54,...tarutoHealsV54].filter(skill=>state.level>=skill.lv).map(skill=>`<span><b>${skill.name}</b><em>LV${skill.lv}・MP ${skill.mp}</em><small>${skill.effect}</small></span>`).join('');const details=$('#mapMayuDetails');details.classList.toggle('hidden',!state.mayuJoined);if(state.mayuJoined){const mayu=mayuStats(),mayuNext=state.mayuLevel>=MAX_LEVEL?'MAX':Math.max(0,expForNext(state.mayuLevel)-state.mayuExp);$('#mapMayuParameters').innerHTML=[['レベル',`${state.mayuLevel}/${MAX_LEVEL}`],['HP',`${mayu.maxHp}/${mayu.maxHp}`],['MP',`${mayu.maxMp}/${mayu.maxMp}`],['こうげき',mayu.atk],['ぼうぎょ',mayu.def],['すばやさ',mayu.spd],['経験値',state.mayuExp],['次のレベルまで',mayuNext]].map(([label,value])=>`<span><small>${label}</small><b>${value}</b></span>`).join('');$('#mapMayuSkills').innerHTML=[...mayuSpecialsV54,...mayuHealsV54].filter(skill=>state.mayuLevel>=skill.lv).map(skill=>`<span><b>${skill.name}</b><em>LV${skill.lv}・MP ${skill.mp}</em><small>${skill.effect}</small></span>`).join('')}$('#mapStatusMenu').classList.remove('hidden');beep(620,.08)};
$('#mapStatusBtn').onclick=openMapStatus;
const showHexMapBeforeSkillsV54=showHexMap;
