// Version 5.5: choose a command first, then tap its enemy target.
function chooseEnemyTargetV55(actionName){const targets=aliveEnemies();if(!targets.length)return Promise.resolve(null);closeMenus();$('#commands').classList.add('hidden');$('#battleScreen').classList.add('choosing-enemy');battle.awaitingAtb='enemyTarget';renderEnemies();$$('.enemy-unit').forEach(unit=>unit.classList.remove('target'));log(`${actionName}を使う敵をタップしてください`);return new Promise(resolve=>{battle.enemyTargetResolver=enemy=>{battle.enemyTargetResolver=null;$('#battleScreen').classList.remove('choosing-enemy');const cancelButton=$('#enemyTargetCancelV55');if(cancelButton)cancelButton.remove();resolve(enemy)};const cancel=document.createElement('button');cancel.id='enemyTargetCancelV55';cancel.className='enemy-target-cancel';cancel.type='button';cancel.textContent='やめる';cancel.onclick=()=>{battle.enemyTargetResolver=null;$('#battleScreen').classList.remove('choosing-enemy');cancel.remove();battle.awaitingAtb='hero';busy=false;$('#commands').classList.remove('hidden');renderEnemies();resolve(null)};$('#battleScreen').appendChild(cancel)})}
const selectEnemyBeforeV55=selectEnemy;
selectEnemy=function(id){if(battle&&battle.enemyTargetResolver){const enemy=aliveEnemies().find(item=>item.id===id);if(!enemy)return;battle.selectedId=id;renderEnemies();beep(520,.08);battle.enemyTargetResolver(enemy);return}if(battle&&battle.atbMode){log('先にコマンドを選んでください');beep(180,.08);return}selectEnemyBeforeV55(id)};
const tarutoSingleEnemyTypesV55=new Set(['attack','nibble','spin','bite','tackle','supreme']);
const actBeforeEnemyTargetV55=act;
act=async function(type){if(!battle||!battle.atbMode||!tarutoSingleEnemyTypesV55.has(type))return actBeforeEnemyTargetV55(type);if(busy||battle.awaitingAtb!=='hero')return;const def=allTarutoActionsV54.find(item=>item.type===type),name=def?def.name:'こうげき';if(def&&state.mp<def.mp){log(`「${name}」を使うMPが足りない！`);return}const target=await chooseEnemyTargetV55(name);if(!target)return;battle.awaitingAtb='hero';return actBeforeEnemyTargetV55(type)};
const submitMayuActionBeforeEnemyTargetV55=submitMayuActionV54;
submitMayuActionV54=async function(type){const def=allMayuActionsV54.find(item=>item.type===type);if(!def||!['m_attack','m_report'].includes(type))return submitMayuActionBeforeEnemyTargetV55(type);if(!battle||!battle.atbMode||busy||battle.awaitingAtb!=='mayu')return;if(battle.mayu.mp<def.mp){log(`まゆのMPが足りない！ MP${def.mp}必要。`);return}const target=await chooseEnemyTargetV55(def.name);if(!target){battle.awaitingAtb='mayu';$('#commands').classList.add('hidden');$('#mayuCommandMenu').classList.remove('hidden');return}battle.awaitingAtb='mayu';return submitMayuActionBeforeEnemyTargetV55(type)};

// Version 5.6: begin each battle with speed-relative ATB gauges.
function seedOpeningAtbV56(){if(!battle||!battle.atbMode)return;syncAtbGauges();const actors=atbActors();if(!actors.length)return;const fastest=Math.max.apply(null,actors.map(actor=>Math.max(0.01,actor.spd)));actors.forEach(actor=>{battle.atb[actor.key]=Math.round(50*Math.max(0,actor.spd)/fastest)});renderAtbMeters()}
const startBattleBeforeOpeningAtbV56=startBattle;
