// Version 5.7: color-coded spiky badges for damage, recovery and status effects.
function statusBadgeV57(text,enemy=null,partyKey='hero',kind='effect'){showNumber(text,kind,enemy,partyKey)}
const executeTarutoActionBeforeBadgesV57=executeTarutoActionV54;
executeTarutoActionV54=async function(def,target){await executeTarutoActionBeforeBadgesV57(def,target);const enemy=activeEnemy();if(def.type==='spin')statusBadgeV57('行動不能',enemy);else if(def.type==='bite')statusBadgeV57('出血',enemy);else if(def.type==='bark')aliveEnemies().forEach(item=>statusBadgeV57('攻撃↓',item));else if(def.type==='dig')statusBadgeV57('完全回避');else if(def.type==='snack'||def.type==='motherSupport')statusBadgeV57('攻撃↑');else if(def.type==='h_father')statusBadgeV57('継続回復');else if(def.type==='h_mother'||def.type==='h_friendship')statusBadgeV57('復活',null,target&&target.key||'hero','heal');else if(def.type==='h_angel')statusBadgeV57('自動復活',null,target&&target.key||'hero')};
const executeMayuActionBeforeBadgesV57=executeMayuActionV54;
executeMayuActionV54=async function(def,target){await executeMayuActionBeforeBadgesV57(def,target);if(def.type==='m_seminar')aliveEnemies().forEach(item=>statusBadgeV57('攻撃↓',item));else if(def.type==='mh_circle')statusBadgeV57('継続回復',null,'mayu');else if(def.type==='mh_retest'||def.type==='mh_album')statusBadgeV57('復活',null,target&&target.key||'hero','heal');else if(def.type==='mh_youth')statusBadgeV57('自動復活',null,target&&target.key||'hero')};
const enemyActionBeforeBadgesV57=enemyAction;
enemyAction=async function(enemy,s){const ailments=ensureHeroAilments(),before={},labels={stun:'行動不能',bleed:'出血',poison:'毒',frost:'霜焼け',burn:'火傷',confuse:'混乱',speedDown:'速さ↓',damageDown:'攻撃↓'};Object.keys(labels).forEach(key=>before[key]=ailments[key]||0);const evadeBefore=enemy.evadeHeroTurns||0,guardBefore=enemy.guardTurns||0;const result=await enemyActionBeforeBadgesV57(enemy,s);const added=Object.keys(labels).filter(key=>(ailments[key]||0)>before[key]);if(added.length){await wait(120);added.forEach(key=>statusBadgeV57(labels[key]))}if((enemy.evadeHeroTurns||0)>evadeBefore)statusBadgeV57('回避',enemy);if((enemy.guardTurns||0)>guardBefore)statusBadgeV57('防御',enemy);return result};

// Version 5.8: Mayu uses the same command-first layout as Taruto.
function renderMayuRootV58(){const menu=$('#mayuCommandMenu');menu.classList.add('mayu-root-menu');menu.innerHTML=`<button type="button" data-mayu-root="attack"><span>⚔</span><b>こうげき</b></button><button type="button" data-mayu-root="special"><span>✨</span><b>必殺技</b><small>攻撃系</small></button><button type="button" data-mayu-root="guard"><span>🛡</span><b>まもる</b></button><button type="button" data-mayu-root="heal"><span>💚</span><b>回復</b><small>回復技</small></button><button type="button" data-mayu-root="effects"><span>📖</span><b>効果一覧</b></button>`;menu.querySelector('[data-mayu-root="attack"]').onclick=()=>submitMayuActionV54('m_attack');menu.querySelector('[data-mayu-root="special"]').onclick=()=>renderMayuSubmenuV58('special');menu.querySelector('[data-mayu-root="guard"]').onclick=submitMayuGuardV58;menu.querySelector('[data-mayu-root="heal"]').onclick=()=>renderMayuSubmenuV58('heal');menu.querySelector('[data-mayu-root="effects"]').onclick=openMayuEffectsV58}
function renderMayuSubmenuV58(kind){const menu=$('#mayuCommandMenu'),lv=battle.mayu.level,list=(kind==='special'?mayuSpecialsV54:mayuHealsV54).filter(def=>lv>=def.lv&&(kind!=='special'||def.type!=='m_attack'));menu.classList.remove('mayu-root-menu');menu.innerHTML=`<div class="mayu-skill-heading">${kind==='special'?'必殺技':'回復技'}</div>${list.map(def=>skillButtonV54(def,'data-mayu-v58')).join('')}<button class="skill-back" type="button">← もどる</button>`;menu.querySelectorAll('[data-mayu-v58]').forEach(button=>button.onclick=()=>submitMayuActionV54(button.dataset.mayuV58));menu.querySelector('.skill-back').onclick=renderMayuRootV58}
renderMayuCommandsV54=renderMayuRootV58;
