async function runAtbTickV511(){if(atbTickBusy||!battle||!battle.atbMode||battle.awaitingAtb||$('#battleScreen').classList.contains('hidden'))return;atbTickBusy=true;let actingKey='';try{if(await finishAtbBattle())return;syncAtbGauges();const actors=atbActors();actors.forEach(actor=>battle.atb[actor.key]=Math.min(100,(battle.atb[actor.key]||0)+1.2+actor.spd/25));renderAtbMeters();const ready=actors.filter(actor=>battle.atb[actor.key]>=100).sort((a,b)=>b.spd-a.spd)[0];if(!ready)return;actingKey=ready.key;if(ready.kind==='hero'){const ailments=ensureHeroAilments();if(ailments.stun>0||ailments.burn>0){battle.atb.hero=0;if(ailments.stun>0)ailments.stun--;log('たるとは行動できない！ ATBゲージがリセットされた！');await applyHeroAilmentTick(stats());renderAtbMeters('hero');await wait(420);return}battle.awaitingAtb='hero';busy=false;closeMenus();$('#skillMenu').classList.add('hidden');$('#healMenu').classList.add('hidden');$('#commands').classList.remove('hidden');$$('#commands button,#skillMenu button,#healMenu button').forEach(button=>button.disabled=false);log('たるとのATBゲージが満タン！ 行動を選んでください');renderAtbMeters('hero');return}if(ready.kind==='mayu'){battle.awaitingAtb='mayu';busy=false;$('#commands').classList.add('hidden');renderMayuRootV58();$('#mayuCommandMenu').classList.remove('hidden');const mpLabel=$('#mayuCommandMp');if(mpLabel)mpLabel.textContent=`MP ${battle.mayu.mp}/${battle.mayu.maxMp}`;log('まゆのATBゲージが満タン！ 行動を選んでください');renderAtbMeters('mayu');return}battle.atb[ready.key]=0;renderAtbMeters(ready.key);await enemyAction(ready.enemy,stats());if(battle.fled||$('#battleScreen').classList.contains('hidden')){stopAtb();return}battle.guard=false;await finishAtbBattle()}catch(error){console.error('ATB recovery',error);if(battle&&battle.atbMode){if(actingKey&&Number.isFinite(battle.atb[actingKey]))battle.atb[actingKey]=0;battle.awaitingAtb=null;busy=false;$('#commands').classList.add('hidden');$('#mayuCommandMenu').classList.add('hidden');log('ATB処理を自動復旧しました。バトルを続けます！');renderAtbMeters()}}finally{atbTickBusy=false}}
