function atbHeartbeatV513(){if(!battle||!battle.atbMode||battle.awaitingAtb||$('#battleScreen').classList.contains('hidden'))return;try{syncAtbGauges();const actors=atbActors();if(!actors.length)return;actors.forEach(actor=>battle.atb[actor.key]=Math.min(100,(battle.atb[actor.key]||0)+1.2+actor.spd/25));renderAtbMeters();const ready=actors.filter(actor=>battle.atb[actor.key]>=99.5).sort((a,b)=>b.spd-a.spd)[0];if(!ready)return;battle.atb[ready.key]=100;if(ready.kind==='hero'){const ailments=ensureHeroAilments();if(ailments.stun<=0&&ailments.burn<=0){openHeroAtbCommandV513();return}battle.awaitingAtb='resolving';battle.atb.hero=0;if(ailments.stun>0)ailments.stun--;Promise.resolve(applyHeroAilmentTick(stats())).then(()=>recoverAtbHeartbeatV513('hero','たるとは状態異常で行動できなかった！')).catch(()=>recoverAtbHeartbeatV513('hero','ATBを復旧してバトルを続けます！'));return}if(ready.kind==='mayu'){openMayuAtbCommandV513();return}battle.awaitingAtb='enemyResolving';battle.atb[ready.key]=0;busy=true;renderAtbMeters(ready.key);Promise.resolve(enemyAction(ready.enemy,stats())).then(async()=>{if(!battle||!battle.atbMode)return;battle.guard=false;if(await finishAtbBattle())return;recoverAtbHeartbeatV513(ready.key)}).catch(error=>{console.error('Enemy ATB recovery',error);recoverAtbHeartbeatV513(ready.key,'敵の行動処理を復旧しました。バトルを続けます！')})}catch(error){console.error('ATB heartbeat recovery',error);recoverAtbHeartbeatV513('', 'ATBを自動復旧しました。バトルを続けます！')}}
