// Version 5.14: independent stall detector and last-resort ATB recovery.
let atbWatchValueV514=-1,atbWatchChangedV514=Date.now(),atbRescuingV514=false;
function rescueStalledAtbV514(){if(atbRescuingV514||!battle||!battle.atbMode||$('#battleScreen').classList.contains('hidden'))return;if(battle.awaitingAtb){atbWatchValueV514=-1;atbWatchChangedV514=Date.now();return}const actors=atbActors();if(!actors.length)return;const total=actors.reduce((sum,actor)=>sum+(battle.atb[actor.key]||0),0),now=Date.now();if(Math.abs(total-atbWatchValueV514)>.05){atbWatchValueV514=total;atbWatchChangedV514=now}else if(now-atbWatchChangedV514>900){if(atbTimer)clearInterval(atbTimer);atbTickBusy=false;atbTimer=setInterval(atbHeartbeatV513,80);atbWatchChangedV514=now}const almostReady=actors.filter(actor=>(battle.atb[actor.key]||0)>=97).sort((a,b)=>(battle.atb[b.key]||0)-(battle.atb[a.key]||0))[0];if(!almostReady)return;atbRescuingV514=true;battle.atb[almostReady.key]=100;if(almostReady.kind==='hero')openHeroAtbCommandV513();else if(almostReady.kind==='mayu')openMayuAtbCommandV513();else{atbHeartbeatV513()}setTimeout(()=>{atbRescuingV514=false},120)}
