const buildHexMapBeforeDiscoveryV5170=buildHexMap;
buildHexMap=function(board,seed=9271){const map=buildHexMapBeforeDiscoveryV5170(board,seed);map.cells.forEach(cell=>{if(cell.type==='xp'||cell.type==='heal')cell.type='normal'});const candidates=seededShuffle(map.cells.filter(cell=>cell.type==='normal'&&cell.col>1&&cell.col<HEX_COLS-2).map(cell=>cell.id),seed+board*811+170),take=(count,type,filter=()=>true)=>{let placed=0;for(const id of candidates){const cell=map.cells[id];if(placed>=count)break;if(cell.type==='normal'&&filter(cell)){cell.type=type;placed++}}};take(4,'xp');take(4,'heal');take(board===0?4:12,'poison');take(board===0?0:6,'magma');const objectiveCandidates=seededShuffle(map.cells.filter(cell=>cell.type==='normal'&&cell.col>=7&&cell.id!==HEX_COUNT-1).map(cell=>cell.id),seed+board*1297+5170);map.objectiveId=objectiveCandidates[0];return map};

